/* ---------- the TV look: scanlines + vignette ---------- */

/* Full-bleed glass over the whole game — on by default, toggled in
   Options > Display. Pointer-events stay off; the game plays identically. */
#tv-overlay {
  position: fixed;
  inset: 0;
  z-index: 48;
  pointer-events: none;
  display: none;
}
body.tv-on #tv-overlay { display: block; }
#tv-overlay > div { position: absolute; inset: 0; }

/* Curved-glass shading: darkened edges, soft center */
.tv-vignette {
  background: radial-gradient(ellipse at 50% 50%,
    transparent 56%, rgba(13, 14, 31, 0.34) 86%, rgba(13, 14, 31, 0.6));
}

/* Horizontal scanlines */
.tv-scanlines {
  background: repeating-linear-gradient(0deg,
    rgba(18, 19, 42, 0.26) 0px, rgba(18, 19, 42, 0.26) 1px,
    transparent 1px, transparent 3px);
}

/* Crossfade overlay between views */
#fade {
  position: fixed;
  inset: 0;
  background: #0D0E1F;
  opacity: 0;
  pointer-events: none;
  z-index: 40;
  transition: opacity 0.65s ease;
}
#fade.show { opacity: 1; }

/* First-person island HUD */
#crosshair {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 10px;
  height: 10px;
  margin: -5px 0 0 -5px;
  border: 1.5px solid rgba(240, 238, 248, 0.7);
  border-radius: 50%;
  box-shadow: 0 0 8px rgba(245, 196, 64, 0.6);
}

/* Level 1 shooter — aiming reticle that tracks the cursor */
#shooter-reticle {
  position: absolute;

