input.new_string:
/* Horizontal scanlines — kept faint so text stays legible; the "old TV"
   feel comes from the static bursts below, not from line density */
.tv-scanlines {
  background: repeating-linear-gradient(0deg,
    rgba(18, 19, 42, 0.09) 0px, rgba(18, 19, 42, 0.09) 1px,
    transparent 1px, transparent 3px);
}

/* Static bursts — a noise field that sits at zero opacity and flashes in
   for ~150ms at irregular points in a long cycle, like a weak signal.
   Two layers on offset cycles so the flashes don't feel metronomic. */
.tv-static,
.tv-static::after {
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="220" height="220"><filter id="n"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="matrix" values="0 0 0 0 0.82  0 0 0 0 0.82  0 0 0 0 0.9  0 0 0 0.9 0"/></filter><rect width="220" height="220" filter="url(%23n)"/></svg>');
  background-size: 220px 220px;
  opacity: 0;
}
.tv-static { animation: tv-static-a 11s steps(1) infinite; }
.tv-static::after {
  content: "";
  position: absolute;
  inset: 0;
  animation: tv-static-b 17s steps(1) infinite;
}

@keyframes tv-static-a {
  0%, 100% { opacity: 0; }
  23%   { opacity: 0.22; background-position: 0 0; }
  23.6% { opacity: 0.16; background-position: -80px 45px; }
  24.2% { opacity: 0; }
  61%   { opacity: 0.18; background-position: 60px -30px; }
  61.5% { opacity: 0.24; background-position: -40px 90px; }
  62.2% { opacity: 0; }
}
@keyframes tv-static-b {
  0%, 100% { opacity: 0; }
  9%    { opacity: 0.2; background-position: 30px 60px; }
  9.5%  { opacity: 0.13; background-position: -100px -20px; }
  10.1% { opacity: 0; }
  44%   { opacity: 0.26; background-position: -20px -70px; }
  44.4% { opacity: 0.17; background-position: 70px 20px; }
  45.3% { opacity: 0; }
  78%   { opacity: 0.15; background-position: 50px -50px; }
  78.6% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .tv-static, .tv-static::after { animation: none; }
}

